'use strict';

/**
* Immutably unset a value at a path in a document using structural sharing.
*
* @module @stdlib/utils/json-patch/base/unset
*
* @example
* var unset = require( '@stdlib/utils/json-patch/base/unset' );
*
* var doc = {
*     'a': {
*         'b': 1,
*         'c': 2
*     }
* };
* var out = unset( doc, [ 'a', 'b' ] );
* // returns { 'a': { 'c': 2 } }
*
* var bool = ( doc.a === out.a );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
